    const payments=state.payments.filter(x=>x.personId===p.id).sort((a,b)=>b.date.localeCompare(a.date)),personAdjustmentRows=(state.adjustments||[]).filter(x=>x.personId===p.id).sort((a,b)=>b.date.localeCompare(a.date));
    const monthPayments=payments.filter(x=>competenceOf(x)===selectedPersonMonth),monthAdjustments=personAdjustmentRows.filter(x=>competenceOf(x)===selectedPersonMonth),year=Number(selectedPersonMonth.slice(0,4));
    const extraMonths=[...payments.map(competenceOf),...personAdjustmentRows.map(competenceOf),...(p.type==='employee'?employeeDebtPlans(p.id):contractorAdvancePlans(p.id)).flatMap(d=>(d.schedule||[]).map(i=>i.month))].filter(Boolean);
    let metrics='',monthNote='';
